--
-- Name: generate_booking_reference(); Type: FUNCTION; Schema: public; Owner: rtvoyage_user
--

CREATE FUNCTION public.generate_booking_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.reference IS NULL OR NEW.reference = '' THEN
    NEW.reference := 'RTV' || UPPER(SUBSTRING(MD5(RANDOM()::TEXT) FROM 1 FOR 8));
  END IF;
  RETURN NEW;
END;
$$;


