--
-- Name: increment_dest_view(); Type: FUNCTION; Schema: public; Owner: rtvoyage_user
--

CREATE FUNCTION public.increment_dest_view() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE destinations SET view_count = view_count + 1 WHERE id = NEW.id;
  RETURN NEW;
END;
$$;


