--
-- Name: v_active_promotions; Type: VIEW; Schema: public; Owner: rtvoyage_user
--

CREATE VIEW public.v_active_promotions AS
 SELECT p.id,
    p.slug,
    p.title_fr,
    p.title_en,
    p.description_fr,
    p.description_en,
    p.image,
    p.promo_type,
    p.destination_id,
    p.original_price,
    p.promo_price,
    p.discount_percent,
    p.currency,
    p.promo_code,
    p.valid_from,
    p.valid_until,
    p.is_active,
    p.is_featured,
    p.created_at,
    d.name_fr AS dest_name_fr,
    d.image_main AS dest_image
   FROM (public.promotions p
     LEFT JOIN public.destinations d ON ((d.id = p.destination_id)))
  WHERE ((p.is_active = true) AND ((p.valid_until IS NULL) OR (p.valid_until >= CURRENT_DATE)));


ALTER VIEW public.v_active_promotions OWNER TO rtvoyage_user;

--
-- Name: v_booking_stats; Type: VIEW; Schema: public; Owner: rtvoyage_user
--

CREATE VIEW public.v_booking_stats AS
 SELECT date_trunc('month'::text, created_at) AS month,
    count(*) AS total,
    sum(total_price) AS revenue,
    count(*) FILTER (WHERE ((status)::text = 'confirmed'::text)) AS confirmed
   FROM public.bookings
  GROUP BY (date_trunc('month'::text, created_at))
  ORDER BY (date_trunc('month'::text, created_at));


ALTER VIEW public.v_booking_stats OWNER TO rtvoyage_user;

--
-- Name: v_destination_stats; Type: VIEW; Schema: public; Owner: rtvoyage_user
--

CREATE VIEW public.v_destination_stats AS
SELECT
    NULL::integer AS id,
    NULL::character varying(120) AS name_fr,
    NULL::integer AS view_count,
    NULL::bigint AS testimonial_count,
    NULL::numeric AS avg_rating,
    NULL::bigint AS hotel_count;


ALTER VIEW public.v_destination_stats OWNER TO rtvoyage_user;

--
-- Name: v_featured_posts; Type: VIEW; Schema: public; Owner: rtvoyage_user
--

CREATE VIEW public.v_featured_posts AS
 SELECT bp.id,
    bp.slug,
    bp.title_fr,
    bp.title_en,
    bp.excerpt_fr,
    bp.excerpt_en,
    bp.content_fr,
    bp.content_en,
    bp.image_main,
    bp.image_alt_fr,
    bp.category_id,
    bp.author_id,
    bp.meta_title_fr,
    bp.meta_desc_fr,
    bp.is_published,
    bp.is_featured,
    bp.view_count,
    bp.published_at,
    bp.created_at,
    bp.updated_at,
    (((u.first_name)::text || ' '::text) || (u.last_name)::text) AS author_name,
    bc.name_fr AS category_name_fr,
    bc.slug AS category_slug
   FROM ((public.blog_posts bp
     LEFT JOIN public.users u ON ((u.id = bp.author_id)))
     LEFT JOIN public.blog_categories bc ON ((bc.id = bp.category_id)))
  WHERE (bp.is_published = true)
  ORDER BY bp.is_featured DESC, bp.published_at DESC;


ALTER VIEW public.v_featured_posts OWNER TO rtvoyage_user;

