--
-- Name: v_destination_stats _RETURN; Type: RULE; Schema: public; Owner: rtvoyage_user
--

CREATE OR REPLACE VIEW public.v_destination_stats AS
 SELECT d.id,
    d.name_fr,
    d.view_count,
    count(DISTINCT t.id) AS testimonial_count,
    round(avg(t.rating), 1) AS avg_rating,
    count(DISTINCT h.id) AS hotel_count
   FROM ((public.destinations d
     LEFT JOIN public.testimonials t ON (((t.destination_id = d.id) AND t.is_approved)))
     LEFT JOIN public.hotels h ON (((h.destination_id = d.id) AND h.is_active)))
  WHERE d.is_active
  GROUP BY d.id;


